const upsertWorkspaceUser = `-- name: UpsertWorkspaceUser :one
INSERT INTO workspace_users (workspace_id, user_id, role)
VALUES ($1, $2, $3::workspace_role)
ON CONFLICT (workspace_id, user_id) DO UPDATE
SET role = EXCLUDED.role
RETURNING workspace_id, user_id, role
`

type UpsertWorkspaceUserParams struct {
	WorkspaceID pgtype.UUID   `json:"workspace_id"`
	UserID      pgtype.UUID   `json:"user_id"`
	Column3     WorkspaceRole `json:"column_3"`
}

func (q *Queries) UpsertWorkspaceUser(ctx context.Context, arg UpsertWorkspaceUserParams) (WorkspaceUser, error) {
	row := q.db.QueryRow(ctx, upsertWorkspaceUser, arg.WorkspaceID, arg.UserID, arg.Column3)
	var i WorkspaceUser
	err := row.Scan(&i.WorkspaceID, &i.UserID, &i.Role)
	return i, err
}
